package codec

import (
	"crypto/rand"
	"encoding/binary"
	"sync/atomic"
)

const alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"

var (
	base     = uint64(len(alphabet))
	decodeMap [256]byte
)

func init() {
	for i := range decodeMap {
		decodeMap[i] = 0xFF
	}
	for i := 0; i < len(alphabet); i++ {
		decodeMap[alphabet[i]] = byte(i)
	}
}

type Generator struct {
	counter atomic.Uint64
	machine uint64
}

func NewGenerator() *Generator {
	g := &Generator{}

	var buf [8]byte
	_, _ = rand.Read(buf[:])
	g.machine = binary.BigEndian.Uint64(buf[:])
	g.counter.Store(g.machine)

	return g
}

func (g *Generator) Encode(n uint64) string {
	if n == 0 {
		return string(alphabet[0])
	}

	var buf [11]byte
	i := len(buf)
	for n > 0 && i > 0 {
		i--
		buf[i] = alphabet[n%base]
		n /= base
	}
	return string(buf[i:])
}

func (g *Generator) Generate() string {
	n := g.counter.Add(1)
	return g.Encode(n)
}

func Decode(s string) (uint64, bool) {
	var n uint64
	for i := 0; i < len(s); i++ {
		v := decodeMap[s[i]]
		if v == 0xFF {
			return 0, false
		}
		n = n*base + uint64(v)
	}
	return n, true
}

package store

import (
	"errors"
	"sync"
	"time"
)

var ErrNotFound = errors.New("url not found")
var ErrDuplicate = errors.New("code already exists")

type URLEntry struct {
	Code      string    `json:"code"`
	URL       string    `json:"url"`
	CreatedAt time.Time `json:"created_at"`
	Clicks    uint64    `json:"clicks"`
}

type Store interface {
	Set(code, url string) (URLEntry, error)
	Get(code string) (URLEntry, error)
	Delete(code string) error
	IncrementClicks(code string)
	Exists(code string) bool
	Len() int
}

type MemoryStore struct {
	mu       sync.RWMutex
	entries  map[string]*URLEntry
	codeIdx  map[string]struct{}
	urlIdx   map[string]string
}

func NewMemoryStore() *MemoryStore {
	return &MemoryStore{
		entries: make(map[string]*URLEntry),
		codeIdx: make(map[string]struct{}),
		urlIdx:  make(map[string]string),
	}
}

func (s *MemoryStore) Set(code, url string) (URLEntry, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, exists := s.codeIdx[code]; exists {
		return URLEntry{}, ErrDuplicate
	}

	if existingCode, exists := s.urlIdx[url]; exists {
		entry := s.entries[existingCode]
		return *entry, nil
	}

	entry := &URLEntry{
		Code:      code,
		URL:       url,
		CreatedAt: time.Now().UTC(),
	}
	s.entries[code] = entry
	s.codeIdx[code] = struct{}{}
	s.urlIdx[url] = code

	return *entry, nil
}

func (s *MemoryStore) Get(code string) (URLEntry, error) {
	s.mu.RLock()
	entry, ok := s.entries[code]
	s.mu.RUnlock()

	if !ok {
		return URLEntry{}, ErrNotFound
	}
	return *entry, nil
}

func (s *MemoryStore) Delete(code string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	entry, ok := s.entries[code]
	if !ok {
		return ErrNotFound
	}

	delete(s.urlIdx, entry.URL)
	delete(s.entries, code)
	delete(s.codeIdx, code)
	return nil
}

func (s *MemoryStore) IncrementClicks(code string) {
	s.mu.Lock()
	if entry, ok := s.entries[code]; ok {
		entry.Clicks++
	}
	s.mu.Unlock()
}

func (s *MemoryStore) Exists(code string) bool {
	s.mu.RLock()
	_, ok := s.codeIdx[code]
	s.mu.RUnlock()
	return ok
}

func (s *MemoryStore) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.entries)
}

package ratelimit

import (
	"sync"
	"time"
)

type TokenBucket struct {
	rate       float64
	burst      int
	mu         sync.Mutex
	tokens     float64
	lastUpdate time.Time
}

func NewTokenBucket(rate float64, burst int) *TokenBucket {
	return &TokenBucket{
		rate:       rate,
		burst:      burst,
		tokens:     float64(burst),
		lastUpdate: time.Now(),
	}
}

func (tb *TokenBucket) Allow() bool {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := time.Now()
	elapsed := now.Sub(tb.lastUpdate).Seconds()
	tb.tokens += elapsed * tb.rate
	if tb.tokens > float64(tb.burst) {
		tb.tokens = float64(tb.burst)
	}
	tb.lastUpdate = now

	if tb.tokens >= 1 {
		tb.tokens--
		return true
	}
	return false
}

type Limiter struct {
	mu     sync.Mutex
	rate   float64
	burst  int
	bucket map[string]*TokenBucket
}

func NewLimiter(rate float64, burst int) *Limiter {
	l := &Limiter{
		rate:   rate,
		burst:  burst,
		bucket: make(map[string]*TokenBucket),
	}
	go l.cleanup(5 * time.Minute)
	return l
}

func (l *Limiter) Allow(key string) bool {
	l.mu.Lock()
	b, ok := l.bucket[key]
	if !ok {
		b = NewTokenBucket(l.rate, l.burst)
		l.bucket[key] = b
	}
	l.mu.Unlock()
	return b.Allow()
}

func (l *Limiter) cleanup(interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for range ticker.C {
		l.mu.Lock()
		threshold := time.Now().Add(-interval)
		for k, b := range l.bucket {
			b.mu.Lock()
			last := b.lastUpdate
			b.mu.Unlock()
			if last.Before(threshold) {
				delete(l.bucket, k)
			}
		}
		l.mu.Unlock()
	}
}

package analytics

import (
	"sync"
	"time"
)

type Click struct {
	IP        string    `json:"ip"`
	UserAgent string    `json:"user_agent"`
	Referer   string    `json:"referer"`
	Timestamp time.Time `json:"timestamp"`
}

type ClickStats struct {
	Code        string            `json:"code"`
	TotalClicks uint64            `json:"total_clicks"`
	Recent      []Click           `json:"recent,omitempty"`
	ByDay       map[string]uint64 `json:"by_day,omitempty"`
	ByReferer   map[string]uint64 `json:"by_referer,omitempty"`
}

type Tracker struct {
	mu       sync.RWMutex
	clicks   map[string][]Click
	maxClicks int
}

func NewTracker(maxClicks int) *Tracker {
	return &Tracker{
		clicks:    make(map[string][]Click),
		maxClicks: maxClicks,
	}
}

func (t *Tracker) Record(code string, ip, userAgent, referer string) {
	t.mu.Lock()
	defer t.mu.Unlock()

	click := Click{
		IP:        ip,
		UserAgent: userAgent,
		Referer:   referer,
		Timestamp: time.Now().UTC(),
	}

	clicks := t.clicks[code]
	clicks = append(clicks, click)
	if len(clicks) > t.maxClicks {
		clicks = clicks[len(clicks)-t.maxClicks:]
	}
	t.clicks[code] = clicks
}

func (t *Tracker) Stats(code string) ClickStats {
	t.mu.RLock()
	defer t.mu.RUnlock()

	clicks := t.clicks[code]
	stats := ClickStats{
		Code:        code,
		TotalClicks: uint64(len(clicks)),
		ByDay:       make(map[string]uint64),
		ByReferer:   make(map[string]uint64),
	}

	for _, c := range clicks {
		day := c.Timestamp.Format("2006-01-02")
		stats.ByDay[day]++
		if c.Referer != "" {
			stats.ByReferer[c.Referer]++
		}
	}

	if len(clicks) > 0 {
		recent := clicks
		if len(recent) > 20 {
			recent = recent[len(recent)-20:]
		}
		stats.Recent = recent
	}

	return stats
}

package handler

import (
	"encoding/json"
	"net/http"
	"net/url"
	"strings"

	"urlshortener/analytics"
	"urlshortener/codec"
	"urlshortener/ratelimit"
	"urlshortener/store"
)

type ShortenerHandler struct {
	Store     store.Store
	Codec     *codec.Generator
	Limiter   *ratelimit.Limiter
	Tracker   *analytics.Tracker
}

type shortenRequest struct {
	URL string `json:"url"`
}

type shortenResponse struct {
	Code      string `json:"code"`
	ShortURL  string `json:"short_url"`
	LongURL   string `json:"long_url"`
	CreatedAt string `json:"created_at"`
}

type errorResponse struct {
	Error string `json:"error"`
}

func (h *ShortenerHandler) Shorten(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeJSON(w, http.StatusMethodNotAllowed, errorResponse{Error: "method not allowed"})
		return
	}

	ip := extractIP(r)
	if !h.Limiter.Allow("shorten:" + ip) {
		writeJSON(w, http.StatusTooManyRequests, errorResponse{Error: "rate limit exceeded"})
		return
	}

	var req shortenRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "invalid request body"})
		return
	}
	r.Body.Close()

	if req.URL == "" {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "url is required"})
		return
	}

	parsed, err := url.Parse(req.URL)
	if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "invalid url"})
		return
	}

	code := h.Codec.Generate()
	entry, err := h.Store.Set(code, req.URL)
	if err != nil {
		writeJSON(w, http.StatusConflict, errorResponse{Error: err.Error()})
		return
	}

	scheme := "http"
	if r.TLS != nil {
		scheme = "https"
	}
	host := r.Host
	if fwd := r.Header.Get("X-Forwarded-Host"); fwd != "" {
		host = fwd
	}

	resp := shortenResponse{
		Code:      entry.Code,
		ShortURL:  scheme + "://" + host + "/" + entry.Code,
		LongURL:   entry.URL,
		CreatedAt: entry.CreatedAt.Format("2006-01-02T15:04:05Z"),
	}

	writeJSON(w, http.StatusCreated, resp)
}

func (h *ShortenerHandler) Redirect(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, errorResponse{Error: "method not allowed"})
		return
	}

	code := strings.TrimPrefix(r.URL.Path, "/")
	if code == "" {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "code is required"})
		return
	}

	entry, err := h.Store.Get(code)
	if err != nil {
		writeJSON(w, http.StatusNotFound, errorResponse{Error: "not found"})
		return
	}

	h.Store.IncrementClicks(code)
	h.Tracker.Record(code, extractIP(r), r.UserAgent(), r.Referer())

	w.Header().Set("Cache-Control", "no-store, no-cache, must-revalidate")
	w.Header().Set("Location", entry.URL)
	w.WriteHeader(http.StatusMovedPermanently)
}

func (h *ShortenerHandler) Stats(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, errorResponse{Error: "method not allowed"})
		return
	}

	code := strings.TrimPrefix(r.URL.Path, "/api/stats/")
	if code == "" {
		writeJSON(w, http.StatusBadRequest, errorResponse{Error: "code is required"})
		return
	}

	entry, err := h.Store.Get(code)
	if err != nil {
		writeJSON(w, http.StatusNotFound, errorResponse{Error: "not found"})
		return
	}

	stats := h.Tracker.Stats(code)
	stats.TotalClicks = entry.Clicks

	writeJSON(w, http.StatusOK, stats)
}

func (h *ShortenerHandler) Health(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, map[string]interface{}{
		"status": "ok",
		"urls":   h.Store.Len(),
	})
}

func writeJSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(data)
}

func extractIP(r *http.Request) string {
	if fwd := r.Header.Get("X-Forwarded-For"); fwd != "" {
		parts := strings.Split(fwd, ",")
		return strings.TrimSpace(parts[0])
	}
	if fwd := r.Header.Get("X-Real-IP"); fwd != "" {
		return fwd
	}
	host := r.RemoteAddr
	if idx := strings.LastIndex(host, ":"); idx != -1 {
		return host[:idx]
	}
	return host
}

package middleware

import (
	"log"
	"net/http"
	"time"
)

func Logger(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s %v", r.Method, r.URL.Path, r.RemoteAddr, time.Since(start))
	})
}

func Recoverer(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if rec := recover(); rec != nil {
				log.Printf("panic recovered: %v", rec)
				http.Error(w, `{"error":"internal server error"}`, http.StatusInternalServerError)
			}
		}()
		next.ServeHTTP(w, r)
	})
}
